<?php
declare(strict_types=1);
class MediaService {
    public function validate(array $file): array {$max=max(1,Env::int('UPLOAD_MAX_IMAGE_MB',5))*1024*1024;if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new InvalidArgumentException('No se recibió una imagen válida.');if((int)$file['size']>$max)throw new InvalidArgumentException('La imagen supera el tamaño permitido.');$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new InvalidArgumentException('Solo se permiten JPG, PNG y WebP.');$dim=getimagesize($file['tmp_name']);if(!$dim)throw new InvalidArgumentException('El archivo no es una imagen válida.');if($dim[0]<Env::int('UPLOAD_IMAGE_MIN_WIDTH',400)||$dim[1]<Env::int('UPLOAD_IMAGE_MIN_HEIGHT',400))throw new InvalidArgumentException('La imagen es demasiado pequeña.');if($dim[0]>Env::int('UPLOAD_IMAGE_MAX_WIDTH',5000)||$dim[1]>Env::int('UPLOAD_IMAGE_MAX_HEIGHT',5000))throw new InvalidArgumentException('La imagen supera las dimensiones permitidas.');return [$mime,$allowed[$mime],$dim];}
    public function store(array $file,int $perfumeId): array {$validation=$this->validate($file);$dir=AppConfig::$data['uploads'].'/perfumes/'.$perfumeId;if(!is_dir($dir))mkdir($dir,0750,true);$name='perfume_'.$perfumeId.'_'.bin2hex(random_bytes(8)).'.'.$validation[1];$target=$dir.'/'.$name;if(!move_uploaded_file($file['tmp_name'],$target))throw new RuntimeException('No fue posible guardar la imagen.');$relative='uploads/perfumes/'.$perfumeId.'/'.$name;return ['image_path'=>$relative,'thumbnail_path'=>null,'alt_text'=>null];}
    public function remove(string $path): void {$root=AppConfig::$data['public'];$full=realpath($root.'/'.ltrim($path,'/'));if($full&&str_starts_with($full,realpath($root.'/uploads')))@unlink($full);}
}
